  s += '<text class="c1" x="100" y="98" text-anchor="middle" style="font:800 22px var(--disp);fill:var(--tinta)">' + esc(centro) + "</text>";
  s += '<text class="c2" x="100" y="117" text-anchor="middle" style="font:500 11.5px var(--corpo);fill:var(--mudo)">' + esc(sob) + "</text>";
  return { svg: s + "</svg>", id: id };
